fn is_integer(text: &Vec<char>) -> bool {
    // An empty vector is considered to consist entirely of digits
    if text.is_empty() {
        return true;
    }

    // Check each character to see if it is a digit
    for &c in text {
        if c < '0' || c > '9' {
            return false; // Found a character that is not a digit
        }
    }

    true // All characters are digits
}